package com.enterprise.siem.agent;
import com.enterprise.siem.model.*; import com.enterprise.siem.security.TlsConfiguration; import com.enterprise.siem.util.JsonUtil; import java.nio.file.*; import java.util.concurrent.*; import java.util.regex.*;
 public final class SecurityAgent implements AutoCloseable { private final String nodeId; private final SIEMClient client; private final ExecutorService workers=Executors.newCachedThreadPool(); private final java.util.List<LogFileWatcher> watchers=new java.util.ArrayList<>(); public SecurityAgent(String nodeId,String host,int port){this(nodeId,host,port,65536,TlsConfiguration.disabled());} public SecurityAgent(String nodeId,String host,int port,int maxLine,TlsConfiguration tls){this.nodeId=nodeId;client=new SIEMClient(host,port,maxLine,tls);}
 public void watch(java.util.List<String> files){for(String value:files){LogFileWatcher watcher=new LogFileWatcher(Path.of(value),this::handle);watchers.add(watcher);workers.submit(watcher);}}
 private void handle(String line){try{EventType type=EventTypeFrom(line);String ip=extract(line,"(?:from|rhost=|src=)([0-9a-fA-F:.]+)");String user=extract(line,"(?:for|user=)(?:invalid user )?([A-Za-z0-9._-]+)");SecurityEvent event=new SecurityEvent(null,java.time.Instant.now(),java.net.InetAddress.getLocalHost().getHostName(),nodeId,level(type),source(type),line,ip,null,user,type,java.util.Map.of());client.send(JsonUtil.write(event));}catch(Exception ignored){}}
 private String source(EventType type){return type==EventType.AUTH_FAILURE||type==EventType.AUTH_SUCCESS?"sshd":"syslog";}
 private String level(EventType type){return type==EventType.AUTH_FAILURE?"WARN":"INFO";}
 private EventType EventTypeFrom(String line){return EventClassifier.classify(line);} private String extract(String line,String regex){var m=Pattern.compile(regex,Pattern.CASE_INSENSITIVE).matcher(line);return m.find()?m.group(1):null;} public void close(){watchers.forEach(LogFileWatcher::stop);workers.shutdownNow();client.close();}
}
